type MarkProps = {
  size?: number | string;
  class?: string;
  style?: JSX.CSSProperties | string;
};

function mark(key: ServiceMarkKey): Component<MarkProps> {
  return (props) => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={props.size ?? 16}
      height={props.size ?? 16}
      class={props.class}
      style={props.style}
      fill="currentColor"
      aria-hidden="true"
    >
      <path d={PATHS[key]} />
    </svg>
  );
}

const MARK_MAP = {
  auth0: mark("auth0"),
  aws: mark("aws"),
  azure: mark("azure"),
  bigquery: mark("bigquery"),
  clerk: mark("clerk"),
  cloudflare: mark("cloudflare"),
  datadog: mark("datadog"),
  digitalocean: mark("digitalocean"),
  docker: mark("docker"),
  elasticsearch: mark("elasticsearch"),
  gcp: mark("gcp"),
  github: mark("github"),
  github_actions: mark("github_actions"),
  gitlab: mark("gitlab"),
  grafana: mark("grafana"),
  graphql: mark("graphql"),
  kafka: mark("kafka"),
  kubernetes: mark("kubernetes"),
  lambda: mark("lambda"),
  mongodb: mark("mongodb"),
  mysql: mark("mysql"),
  nextjs: mark("nextjs"),
  nginx: mark("nginx"),
  openai: mark("openai"),
  postgres: mark("postgres"),
  prisma: mark("prisma"),
  prometheus: mark("prometheus"),
  rabbitmq: mark("rabbitmq"),
  redis: mark("redis"),
  s3: mark("s3"),
  snowflake: mark("snowflake"),
  sqs: mark("sqs"),
  stripe: mark("stripe"),
  supabase: mark("supabase"),
  terraform: mark("terraform"),
  vercel: mark("vercel"),
} satisfies Record<ServiceMarkKey, Component<MarkProps>>;

/** Architecture product mark with soft brand color. Returns null if unknown. */
export function ServiceMark(props: {
  name: string;
  size?: number;
  class?: string;
  brand?: boolean;
}): JSX.Element | null {
  if (!hasServiceMark(props.name)) return null;
  const key = props.name;
  const Icon = MARK_MAP[key];
  return (
    <Icon
      size={props.size ?? 16}
      class={props.class}
      style={props.brand === false ? undefined : { color: SERVICE_MARK_TINT[key] }}
    />
  );
}
